mapper.select:
SELECT id, tenant_id AS tenantId, task_name AS taskName, business_type AS businessType, status, started_at AS startedAt, finished_at AS finishedAt, created_at AS createdAt FROM marketing_task WHERE deleted_at IS NULL AND id IN
#{taskId}
ORDER BY FIELD(id,
#{taskId}
)

SELECT 
FROM marketing_task_export_job
WHERE id = #{id}
  AND created_by = #{createdBy}

SELECT 
FROM marketing_task_export_job
WHERE tenant_id = #{tenantId}
  AND created_by = #{createdBy}
  AND request_hash = #{requestHash}
  AND status IN ('PENDING', 'PROCESSING')
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE marketing_task_export_job
SET storage_key = NULL,
    content_type = NULL,
    file_size = NULL,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'SUCCESS'
  AND expires_at <= #{now}
  AND storage_key = #{storageKey}

UPDATE marketing_task_export_job
SET lease_until = #{leaseUntil},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET status = 'FAILED',
    error_message = #{errorMessage},
    lease_until = NULL,
    claim_token = NULL,
    finished_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}

mapper.select:
WITH successful_marketing_source AS ( SELECT a.id AS attempt_id, a.tenant_id, a.marketing_task_id, TRIM(a.group_jid) AS group_jid, a.group_link_id, NULLIF(TRIM(a.group_name), '') AS group_name, t.account_id AS sender_account_id, NULLIF(TRIM(t.account_phone), '') AS sender_phone, COALESCE(a.result_at, a.attempted_at, a.created_at) AS event_at FROM marketing_task_send_attempt a JOIN marketing_task_target t ON t.id = a.target_id AND t.marketing_task_id = a.marketing_task_id AND t.tenant_id = a.tenant_id WHERE a.tenant_id = #{tenantId} AND a.status = 1 AND a.group_jid IS NOT NULL AND TRIM(a.group_jid) <> '' AND ((a.result_at IS NOT NULL AND a.result_at <= #{snapshotAt}) OR (a.result_at IS NULL AND a.submitted_at IS NULL AND COALESCE(a.attempted_at, a.created_at) <= #{snapshotAt})) AND a.marketing_task_id IN
#{taskId}
), successful_marketing AS ( SELECT ranked.* FROM ( SELECT source.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid ORDER BY event_at DESC, attempt_id DESC) AS sender_rank, COUNT(*) OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid) AS marketing_count FROM successful_marketing_source source ) ranked WHERE ranked.sender_rank = 1 ), group_status_source AS ( SELECT a.id AS attempt_id, a.tenant_id, a.marketing_task_id, COALESCE(NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), '')) AS group_jid, a.status AS projected_status, a.reason_code, a.group_status, a.group_status_reason, a.round_no, a.attempt_no, CASE WHEN a.status = 1 THEN 1 WHEN a.status = 2 AND ( UPPER(TRIM(COALESCE(a.group_status, ''))) IN ('NORMAL', 'BANNED', 'NO_PERMISSION') OR UPPER(TRIM(COALESCE(a.reason_code, ''))) IN ( 'ACCOUNT_BANNED', 'KICKED_OUT', 'ACCOUNT_NOT_PARTICIPANT', 'GROUP_BANNED', 'BANNED', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'NO_PERMISSION', 'ANNOUNCE_ONLY_NON_ADMIN') OR UPPER(TRIM(COALESCE(a.group_status_reason, ''))) IN ( 'GROUP_SEND_ALLOWED', 'ACCOUNT_NOT_PARTICIPANT', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'ANNOUNCE_ONLY_NON_ADMIN')) THEN 1 ELSE 0 END AS effective_group_status FROM marketing_task_send_attempt a JOIN marketing_task_target t ON t.id = a.target_id AND t.marketing_task_id = a.marketing_task_id AND t.tenant_id = a.tenant_id WHERE a.tenant_id = #{tenantId} AND a.status IN (1, 2) AND COALESCE(NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), '')) IS NOT NULL AND ((a.result_at IS NOT NULL AND a.result_at <= #{snapshotAt}) OR (a.result_at IS NULL AND a.submitted_at IS NULL AND COALESCE(a.attempted_at, a.created_at) <= #{snapshotAt})) AND a.marketing_task_id IN
#{taskId}
), latest_group_status AS ( SELECT ranked.* FROM ( SELECT source.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid ORDER BY effective_group_status DESC, round_no DESC, attempt_no DESC, attempt_id DESC) AS status_rank FROM group_status_source source ) ranked WHERE ranked.status_rank = 1 ), country_member_fact_ranked AS ( SELECT fact.*, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY fact.occurred_at DESC, CASE fact.status_source WHEN 'PARTICIPANT_LEAVE' THEN 4 WHEN 'PARTICIPANT_REMOVE' THEN 3 WHEN 'PARTICIPANT_ADD' THEN 2 WHEN 'MEMBER_SNAPSHOT' THEN 1 ELSE 0 END DESC, fact.source_event_id DESC, fact.id DESC) AS state_rank, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY CASE WHEN fact.phone IS NOT NULL AND TRIM(fact.phone) <> '' THEN 0 ELSE 1 END, fact.occurred_at DESC, fact.source_event_id DESC, fact.id DESC) AS identity_rank, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY CASE WHEN fact.role IS NOT NULL OR fact.is_admin IS NOT NULL OR fact.is_owner IS NOT NULL THEN 0 ELSE 1 END, fact.occurred_at DESC, fact.source_event_id DESC, fact.id DESC) AS role_rank FROM whatsapp_group_member_fact fact JOIN ( SELECT DISTINCT tenant_id, group_jid FROM successful_marketing ) selected ON selected.tenant_id = fact.tenant_id AND selected.group_jid = fact.group_jid WHERE fact.occurred_at <= #{snapshotAt} ), country_member_state AS ( SELECT * FROM country_member_fact_ranked WHERE state_rank = 1 ), country_member_identity AS ( SELECT tenant_id, group_jid, member_jid, phone FROM country_member_fact_ranked WHERE identity_rank = 1 AND phone IS NOT NULL AND TRIM(phone) <> '' ), country_member_role AS ( SELECT tenant_id, group_jid, member_jid, is_admin FROM country_member_fact_ranked WHERE role_rank = 1 ), country_current_member_roles AS ( SELECT state.tenant_id, state.group_jid, identity.phone, MAX(member_role.is_admin) AS is_admin FROM country_member_state state JOIN country_member_identity identity ON identity.tenant_id = state.tenant_id AND identity.group_jid = state.group_jid AND identity.member_jid = state.member_jid LEFT JOIN country_member_role member_role ON member_role.tenant_id = state.tenant_id AND member_role.group_jid = state.group_jid AND member_role.member_jid = state.member_jid WHERE state.membership_status = 1 GROUP BY state.tenant_id, state.group_jid, identity.phone ), country_member_history AS ( SELECT tenant_id, group_jid, member_jid, MAX(CASE WHEN status_source = 'PARTICIPANT_ADD' THEN occurred_at END) AS joined_at, MAX(CASE WHEN status_source IN ('PARTICIPANT_REMOVE', 'PARTICIPANT_LEAVE') THEN occurred_at END) AS exited_at FROM country_member_fact_ranked GROUP BY tenant_id, group_jid, member_jid ), country_group_setting_ranked AS ( SELECT snapshot.*, ROW_NUMBER() OVER ( PARTITION BY snapshot.tenant_id, snapshot.group_jid ORDER BY snapshot.snapshot_at DESC, snapshot.source_event_id DESC, snapshot.id DESC) AS setting_rank FROM whatsapp_group_member_snapshot_fact snapshot JOIN ( SELECT DISTINCT tenant_id, group_jid FROM successful_marketing ) selected ON selected.tenant_id = snapshot.tenant_id AND selected.group_jid = snapshot.group_jid WHERE snapshot.snapshot_at <= #{snapshotAt} ), country_group_setting AS ( SELECT * FROM country_group_setting_ranked WHERE setting_rank = 1 ), country_sender_setting_ranked AS ( SELECT selected.marketing_task_id, selected.sender_account_id, snapshot.*, ROW_NUMBER() OVER ( PARTITION BY snapshot.tenant_id, selected.marketing_task_id, snapshot.group_jid, selected.sender_account_id ORDER BY snapshot.snapshot_at DESC, snapshot.source_event_id DESC, snapshot.id DESC) AS sender_setting_rank FROM whatsapp_group_member_snapshot_fact snapshot JOIN successful_marketing selected ON selected.tenant_id = snapshot.tenant_id AND selected.group_jid = snapshot.group_jid AND selected.sender_account_id = snapshot.observer_account_id WHERE snapshot.snapshot_at <= #{snapshotAt} ), country_sender_setting AS ( SELECT * FROM country_sender_setting_ranked WHERE sender_setting_rank = 1 ) SELECT CASE WHEN member.membership_status IN (1, 5) AND history.exited_at IS NOT NULL AND (history.joined_at IS NULL OR history.joined_at <= history.exited_at) THEN NULL ELSE history.joined_at END AS joinedAt, mt.id AS taskId, mt.task_name AS taskName, REGEXP_REPLACE(identity.phone, '[^0-9]', '') AS actualPhone, COALESCE(sm.group_name, NULLIF(TRIM(preview.wa_subject), ''), sm.group_jid) AS groupName, group_link_data.link_url AS groupLink, AS groupStatus, CASE WHEN group_setting.announce_only = 1 AND COALESCE( sender_member.is_admin, CASE WHEN sender_setting.observer_is_admin = 1 AND ((sender_relation.membership_status = 1 AND (sender_relation.joined_at IS NULL OR (sender_relation.joined_at <= #{snapshotAt} AND sender_setting.snapshot_at >= sender_relation.joined_at))) OR (sender_relation.membership_status <> 1 AND sender_relation.status_updated_at > #{snapshotAt} AND (sender_relation.joined_at IS NULL OR sender_setting.snapshot_at >= sender_relation.joined_at))) THEN 1 ELSE 0 END) = 1 THEN '仅管理员可发言（发送账号可发言）' WHEN group_setting.announce_only = 1 THEN '无发言权限' WHEN group_setting.announce_only = 0 THEN '所有成员可发言' ELSE '未确认' END AS speechPermission, sm.sender_phone AS senderPhone, sm.marketing_count AS marketingCount FROM successful_marketing sm JOIN marketing_task mt ON mt.id = sm.marketing_task_id AND mt.tenant_id = sm.tenant_id AND mt.business_type = 1 AND mt.deleted_at IS NULL JOIN country_member_state member ON member.tenant_id = sm.tenant_id AND member.group_jid = sm.group_jid JOIN country_member_identity identity ON identity.tenant_id = member.tenant_id AND identity.group_jid = member.group_jid AND identity.member_jid = member.member_jid LEFT JOIN country_member_history history ON history.tenant_id = member.tenant_id AND history.group_jid = member.group_jid AND history.member_jid = member.member_jid LEFT JOIN country_group_setting group_setting ON group_setting.tenant_id = sm.tenant_id AND group_setting.group_jid = sm.group_jid LEFT JOIN country_sender_setting sender_setting ON sender_setting.tenant_id = sm.tenant_id AND sender_setting.marketing_task_id = sm.marketing_task_id AND sender_setting.group_jid = sm.group_jid AND sender_setting.sender_account_id = sm.sender_account_id LEFT JOIN country_current_member_roles sender_member ON sender_member.tenant_id = sm.tenant_id AND sender_member.group_jid = sm.group_jid AND sender_member.phone = REGEXP_REPLACE(sm.sender_phone, '[^0-9]', '') LEFT JOIN account_group_membership sender_relation ON sender_relation.tenant_id = sm.tenant_id AND sender_relation.account_id = sm.sender_account_id AND sender_relation.group_jid = sm.group_jid AND sender_relation.deleted_at IS NULL LEFT JOIN group_link_preview preview ON preview.group_link_id = sm.group_link_id AND preview.tenant_id = sm.tenant_id AND (preview.group_jid IS NULL OR preview.group_jid = sm.group_jid) LEFT JOIN group_link_health health ON health.group_link_id = sm.group_link_id AND health.tenant_id = sm.tenant_id LEFT JOIN group_link group_link_data ON group_link_data.id = sm.group_link_id AND group_link_data.tenant_id = sm.tenant_id LEFT JOIN latest_group_status protocol ON protocol.tenant_id = sm.tenant_id AND protocol.marketing_task_id = sm.marketing_task_id AND protocol.group_jid = sm.group_jid GROUP BY mt.id, mt.task_name, member.member_jid, member.membership_status, history.joined_at, history.exited_at, REGEXP_REPLACE(identity.phone, '[^0-9]', ''), sm.group_jid, sm.group_name, preview.wa_subject, group_link_data.link_url, health.is_banned, health.health_status, protocol.projected_status, protocol.reason_code, protocol.group_status, protocol.group_status_reason, group_setting.announce_only, sender_member.is_admin, sender_setting.observer_is_admin, sender_setting.snapshot_at, sender_relation.id, sender_relation.membership_status, sender_relation.joined_at, sender_relation.status_updated_at, sm.sender_phone, sm.marketing_count HAVING actualPhone IS NOT NULL AND actualPhone <> '' ORDER BY mt.id ASC, sm.group_jid ASC, actualPhone ASC

mapper.sql:
attempt_source AS ( SELECT a.id AS attempt_id, a.tenant_id, a.marketing_task_id, a.target_id, t.account_id, NULLIF(TRIM(t.account_phone), '') AS account_phone, COALESCE(a.group_link_id, t.group_link_id) AS group_link_id, COALESCE(NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), '')) AS group_jid, COALESCE(NULLIF(TRIM(a.group_name), ''), NULLIF(TRIM(t.group_name), '')) AS group_name, COALESCE( NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), ''), CONCAT('link:', COALESCE(a.group_link_id, t.group_link_id)), CONCAT('target:', t.id)) AS group_key, a.status AS raw_status, a.reason_code, a.reason_message, a.group_status, a.group_status_reason, a.round_no, a.attempt_no, a.attempted_at, a.submitted_at, a.result_at, a.created_at AS attempt_created_at, CASE WHEN a.status = 3 THEN COALESCE(a.attempted_at, a.created_at) ELSE COALESCE(a.submitted_at, a.attempted_at, a.created_at) END AS entered_at FROM marketing_task_send_attempt a JOIN marketing_task_target t ON t.id = a.target_id AND t.marketing_task_id = a.marketing_task_id AND t.tenant_id = a.tenant_id WHERE a.tenant_id = #{tenantId} AND (CASE WHEN a.status = 3 THEN COALESCE(a.attempted_at, a.created_at) ELSE COALESCE(a.submitted_at, a.attempted_at, a.created_at) END) <= #{snapshotAt} AND a.marketing_task_id IN
#{taskId}
), projected_attempts AS ( SELECT source.*, CASE WHEN raw_status IN (1, 2) AND result_at IS NOT NULL AND result_at <= #{snapshotAt} THEN raw_status WHEN raw_status = 3 THEN 3 WHEN raw_status IN (1, 2) AND submitted_at <= #{snapshotAt} AND (result_at IS NULL OR result_at > #{snapshotAt}) THEN 0 WHEN raw_status IN (1, 2) AND result_at IS NULL AND submitted_at IS NULL THEN raw_status ELSE 0 END AS projected_status, CASE WHEN result_at IS NOT NULL AND result_at <= #{snapshotAt} THEN result_at WHEN raw_status = 3 THEN COALESCE(attempted_at, attempt_created_at) ELSE entered_at END AS event_at FROM attempt_source source ), attempt_facts AS ( SELECT projected.*, CASE WHEN projected_status = 1 THEN 1 WHEN projected_status = 2 AND ( UPPER(TRIM(COALESCE(group_status, ''))) IN ('NORMAL', 'BANNED', 'NO_PERMISSION') OR UPPER(TRIM(COALESCE(reason_code, ''))) IN ( 'ACCOUNT_BANNED', 'KICKED_OUT', 'ACCOUNT_NOT_PARTICIPANT', 'GROUP_BANNED', 'BANNED', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'NO_PERMISSION', 'ANNOUNCE_ONLY_NON_ADMIN') OR UPPER(TRIM(COALESCE(group_status_reason, ''))) IN ( 'GROUP_SEND_ALLOWED', 'ACCOUNT_NOT_PARTICIPANT', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'ANNOUNCE_ONLY_NON_ADMIN')) THEN 1 ELSE 0 END AS effective_group_status FROM projected_attempts projected ), fixed_target_groups AS ( SELECT t.tenant_id, t.marketing_task_id, COALESCE(NULLIF(TRIM(t.group_jid), ''), NULLIF(TRIM(p.group_jid), ''), CONCAT('link:', t.group_link_id), CONCAT('target:', t.id)) AS group_key, MIN(t.created_at) AS joined_task_at, MAX(t.group_link_id) AS group_link_id, MAX(COALESCE(NULLIF(TRIM(t.group_jid), ''), NULLIF(TRIM(p.group_jid), ''))) AS group_jid, MAX(COALESCE(NULLIF(TRIM(t.group_name), ''), NULLIF(TRIM(g.group_name), ''), NULLIF(TRIM(p.wa_subject), ''))) AS group_name, CAST(SUBSTRING_INDEX(GROUP_CONCAT( t.account_id ORDER BY t.created_at DESC, t.id DESC SEPARATOR '\n'), '\n', 1) AS UNSIGNED) AS sender_account_id, SUBSTRING_INDEX(GROUP_CONCAT( t.account_phone ORDER BY t.created_at DESC, t.id DESC SEPARATOR '\n'), '\n', 1) AS sender_phone FROM marketing_task_target t LEFT JOIN group_link g ON g.id = t.group_link_id AND g.tenant_id = t.tenant_id LEFT JOIN group_link_preview p ON p.group_link_id = t.group_link_id AND p.tenant_id = t.tenant_id WHERE t.tenant_id = #{tenantId} AND COALESCE(t.target_scope, 1) = 1 AND t.created_at <= #{snapshotAt} AND t.marketing_task_id IN
#{taskId}
GROUP BY t.tenant_id, t.marketing_task_id, group_key ), attempt_dimensions AS ( SELECT tenant_id, marketing_task_id, group_key, MIN(attempt_created_at) AS joined_task_at, SUM(CASE WHEN projected_status IN (0, 1, 2) THEN 1 ELSE 0 END) AS planned_count, SUM(CASE WHEN projected_status = 1 THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN projected_status = 2 THEN 1 ELSE 0 END) AS failed_count, SUM(CASE WHEN projected_status = 0 THEN 1 ELSE 0 END) AS unknown_count, MIN(CASE WHEN projected_status <> 3 AND attempted_at <= #{snapshotAt} THEN attempted_at END) AS first_sent_at, MAX(CASE WHEN projected_status <> 3 AND attempted_at <= #{snapshotAt} THEN attempted_at END) AS last_sent_at FROM attempt_facts GROUP BY tenant_id, marketing_task_id, group_key ), group_dimensions AS ( SELECT tenant_id, marketing_task_id, group_key FROM fixed_target_groups UNION SELECT tenant_id, marketing_task_id, group_key FROM attempt_dimensions ), selected_group_jids AS ( SELECT DISTINCT tenant_id, group_jid FROM fixed_target_groups WHERE group_jid IS NOT NULL AND TRIM(group_jid) <> '' UNION SELECT DISTINCT tenant_id, group_jid FROM attempt_source WHERE group_jid IS NOT NULL AND TRIM(group_jid) <> '' ), member_fact_ranked AS ( SELECT fact.*, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY fact.occurred_at DESC, CASE fact.status_source WHEN 'PARTICIPANT_LEAVE' THEN 4 WHEN 'PARTICIPANT_REMOVE' THEN 3 WHEN 'PARTICIPANT_ADD' THEN 2 WHEN 'MEMBER_SNAPSHOT' THEN 1 ELSE 0 END DESC, fact.source_event_id DESC, fact.id DESC) AS state_rank, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY CASE WHEN fact.phone IS NOT NULL AND TRIM(fact.phone) <> '' THEN 0 ELSE 1 END, fact.occurred_at DESC, fact.source_event_id DESC, fact.id DESC) AS identity_rank, ROW_NUMBER() OVER ( PARTITION BY fact.tenant_id, fact.group_jid, fact.member_jid ORDER BY CASE WHEN fact.role IS NOT NULL OR fact.is_admin IS NOT NULL OR fact.is_owner IS NOT NULL THEN 0 ELSE 1 END, fact.occurred_at DESC, fact.source_event_id DESC, fact.id DESC) AS role_rank FROM whatsapp_group_member_fact fact JOIN selected_group_jids selected ON selected.tenant_id = fact.tenant_id AND selected.group_jid = fact.group_jid WHERE fact.occurred_at <= #{snapshotAt} ), member_state AS ( SELECT * FROM member_fact_ranked WHERE state_rank = 1 ), member_identity AS ( SELECT tenant_id, group_jid, member_jid, phone FROM member_fact_ranked WHERE identity_rank = 1 ), member_role AS ( SELECT tenant_id, group_jid, member_jid, role, is_admin, is_owner FROM member_fact_ranked WHERE role_rank = 1 ), member_history AS ( SELECT tenant_id, group_jid, member_jid, MAX(CASE WHEN status_source = 'PARTICIPANT_ADD' THEN occurred_at END) AS joined_at, MAX(CASE WHEN status_source IN ('PARTICIPANT_REMOVE', 'PARTICIPANT_LEAVE') THEN occurred_at END) AS exited_at FROM member_fact_ranked GROUP BY tenant_id, group_jid, member_jid ), current_member_roles AS ( SELECT state.tenant_id, state.group_jid, identity.phone, MAX(member_role.is_admin) AS is_admin FROM member_state state JOIN member_identity identity ON identity.tenant_id = state.tenant_id AND identity.group_jid = state.group_jid AND identity.member_jid = state.member_jid LEFT JOIN member_role member_role ON member_role.tenant_id = state.tenant_id AND member_role.group_jid = state.group_jid AND member_role.member_jid = state.member_jid WHERE state.membership_status = 1 GROUP BY state.tenant_id, state.group_jid, identity.phone ), group_setting_ranked AS ( SELECT snapshot.*, ROW_NUMBER() OVER ( PARTITION BY snapshot.tenant_id, snapshot.group_jid ORDER BY snapshot.snapshot_at DESC, snapshot.source_event_id DESC, snapshot.id DESC) AS setting_rank FROM whatsapp_group_member_snapshot_fact snapshot JOIN selected_group_jids selected ON selected.tenant_id = snapshot.tenant_id AND selected.group_jid = snapshot.group_jid WHERE snapshot.snapshot_at <= #{snapshotAt} ), latest_group_setting AS ( SELECT * FROM group_setting_ranked WHERE setting_rank = 1 ), sender_group_setting_ranked AS ( SELECT snapshot.*, ROW_NUMBER() OVER ( PARTITION BY snapshot.tenant_id, snapshot.group_jid, snapshot.observer_account_id ORDER BY snapshot.snapshot_at DESC, snapshot.source_event_id DESC, snapshot.id DESC) AS sender_setting_rank FROM whatsapp_group_member_snapshot_fact snapshot JOIN selected_group_jids selected ON selected.tenant_id = snapshot.tenant_id AND selected.group_jid = snapshot.group_jid WHERE snapshot.snapshot_at <= #{snapshotAt} ), sender_group_setting AS ( SELECT * FROM sender_group_setting_ranked WHERE sender_setting_rank = 1 ), latest_any AS ( SELECT ranked.* FROM ( SELECT af.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_key ORDER BY round_no DESC, attempt_no DESC, attempt_id DESC) AS row_rank FROM attempt_facts af ) ranked WHERE ranked.row_rank = 1 ), latest_protocol AS ( SELECT ranked.* FROM ( SELECT af.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_key ORDER BY effective_group_status DESC, round_no DESC, attempt_no DESC, attempt_id DESC) AS protocol_rank FROM attempt_facts af WHERE projected_status IN (1, 2) ) ranked WHERE ranked.protocol_rank = 1 ), latest_ended AS ( SELECT ranked.* FROM ( SELECT af.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_key ORDER BY round_no DESC, attempt_no DESC, attempt_id DESC) AS ended_rank FROM attempt_facts af WHERE projected_status IN (1, 2, 3) ) ranked WHERE ranked.ended_rank = 1 ), latest_failure_round AS ( SELECT tenant_id, marketing_task_id, group_key, MAX(round_no) AS round_no FROM attempt_facts WHERE projected_status = 2 GROUP BY tenant_id, marketing_task_id, group_key ), failure_reasons AS ( SELECT af.tenant_id, af.marketing_task_id, af.group_key, GROUP_CONCAT(DISTINCT COALESCE(NULLIF(TRIM(af.reason_message), ''), NULLIF(TRIM(af.reason_code), ''), '未知原因') ORDER BY af.attempt_id ASC SEPARATOR '；') AS failure_reasons FROM attempt_facts af JOIN latest_failure_round latest ON latest.tenant_id = af.tenant_id AND latest.marketing_task_id = af.marketing_task_id AND latest.group_key = af.group_key AND latest.round_no = af.round_no WHERE af.projected_status = 2 GROUP BY af.tenant_id, af.marketing_task_id, af.group_key ), successful_join_members AS ( SELECT member_join.tenant_id, member_join.group_jid, REGEXP_REPLACE( COALESCE(NULLIF(TRIM(joined_account.ws_phone), ''), NULLIF(TRIM(member_join.account), '')), '[^0-9]', '') AS phone, MAX(COALESCE(member_join.joined_at, member_join.updated_at, member_join.created_at)) AS joined_at FROM join_task_result member_join LEFT JOIN account joined_account ON joined_account.tenant_id = member_join.tenant_id AND joined_account.id = member_join.account_id AND joined_account.deleted_at IS NULL JOIN selected_group_jids selected ON selected.tenant_id = member_join.tenant_id AND selected.group_jid = member_join.group_jid WHERE member_join.status = 'SUCCESS' AND COALESCE(member_join.joined_at, member_join.updated_at, member_join.created_at) <= #{snapshotAt} GROUP BY member_join.tenant_id, member_join.group_jid, REGEXP_REPLACE( COALESCE(NULLIF(TRIM(joined_account.ws_phone), ''), NULLIF(TRIM(member_join.account), '')), '[^0-9]', '') ), member_counts AS ( SELECT selected.tenant_id, selected.group_jid, CASE WHEN complete.group_jid IS NULL THEN NULL ELSE COUNT(DISTINCT CASE WHEN member.membership_status = 1 THEN member.member_jid END) END AS current_count, COUNT(DISTINCT member.member_jid) AS joined_count FROM selected_group_jids selected LEFT JOIN latest_group_setting complete ON complete.tenant_id = selected.tenant_id AND complete.group_jid = selected.group_jid LEFT JOIN member_state member ON member.tenant_id = selected.tenant_id AND member.group_jid = selected.group_jid GROUP BY selected.tenant_id, selected.group_jid, complete.group_jid ), group_rows AS ( SELECT COALESCE(fixed.joined_task_at, attempts.joined_task_at) AS joinedTaskAt, mt.id AS taskId, mt.task_name AS taskName, COALESCE(NULLIF(TRIM(latest.group_name), ''), NULLIF(TRIM(fixed.group_name), ''), NULLIF(TRIM(preview.wa_subject), ''), COALESCE(latest.group_jid, fixed.group_jid, d.group_key)) AS groupName, COALESCE(latest.group_jid, fixed.group_jid) AS groupJid, group_link.link_url AS groupLink, d.group_key AS groupKey, AS groupStatus, CASE WHEN group_setting.announce_only = 1 AND COALESCE( sender_member.is_admin, CASE WHEN sender_setting.observer_is_admin = 1 AND ((sender_relation.membership_status = 1 AND (sender_relation.joined_at IS NULL OR (sender_relation.joined_at <= #{snapshotAt} AND sender_setting.snapshot_at >= sender_relation.joined_at))) OR (sender_relation.membership_status <> 1 AND sender_relation.status_updated_at > #{snapshotAt} AND (sender_relation.joined_at IS NULL OR sender_setting.snapshot_at >= sender_relation.joined_at))) THEN 1 ELSE 0 END) = 1 THEN '仅管理员可发言（发送账号可发言）' WHEN group_setting.announce_only = 1 THEN '无发言权限' WHEN group_setting.announce_only = 0 THEN '所有成员可发言' ELSE '未确认' END AS speechPermission, members.current_count AS groupMemberCount, COALESCE(members.joined_count, 0) AS joinedPhoneCount, COALESCE(attempts.planned_count, 0) AS plannedCount, COALESCE(attempts.success_count, 0) AS successCount, COALESCE(attempts.failed_count, 0) AS failedCount, COALESCE(attempts.unknown_count, 0) AS unknownCount, COALESCE(latest.account_phone, fixed.sender_phone) AS senderPhone, CASE WHEN account_state.mute_status = 1 THEN '禁言6小时' WHEN account_state.mute_status = 2 THEN '禁言24小时' WHEN account_state.account_state = 1 THEN '新增' WHEN account_state.account_state = 2 THEN '正常' WHEN account_state.account_state = 3 THEN '封禁' WHEN account_state.account_state = 4 THEN '导出' WHEN account_state.account_state = 5 THEN '解绑' WHEN account_state.account_state = 6 THEN '被抢登' WHEN account_state.account_state = 7 THEN '抢登中' WHEN account_state.account_state = 8 THEN '账号受限' ELSE '—' END AS accountStatus, attempts.first_sent_at AS firstSentAt, attempts.last_sent_at AS lastSentAt, CASE WHEN COALESCE(attempts.planned_count, 0) = 0 THEN '未发送' WHEN COALESCE(attempts.unknown_count, 0) > 0 AND mt.status = 2 THEN '发送中' WHEN COALESCE(attempts.success_count, 0) > 0 AND COALESCE(attempts.failed_count, 0) = 0 AND COALESCE(attempts.unknown_count, 0) = 0 THEN '成功' WHEN COALESCE(attempts.success_count, 0) = 0 AND COALESCE(attempts.failed_count, 0) > 0 AND COALESCE(attempts.unknown_count, 0) = 0 THEN '失败' WHEN COALESCE(attempts.success_count, 0) > 0 THEN '部分成功' WHEN COALESCE(attempts.unknown_count, 0) > 0 THEN '结果未知' ELSE '未发送' END AS sendStatus, COALESCE(failures.failure_reasons, CASE WHEN ended.projected_status = 3 THEN COALESCE(NULLIF(TRIM(ended.reason_message), ''), NULLIF(TRIM(ended.reason_code), ''), '本轮已跳过') END) AS failureReason, group_link.remark AS remark FROM group_dimensions d JOIN marketing_task mt ON mt.id = d.marketing_task_id AND mt.tenant_id = d.tenant_id AND mt.business_type = 1 AND mt.deleted_at IS NULL LEFT JOIN fixed_target_groups fixed ON fixed.tenant_id = d.tenant_id AND fixed.marketing_task_id = d.marketing_task_id AND fixed.group_key = d.group_key LEFT JOIN attempt_dimensions attempts ON attempts.tenant_id = d.tenant_id AND attempts.marketing_task_id = d.marketing_task_id AND attempts.group_key = d.group_key LEFT JOIN latest_any latest ON latest.tenant_id = d.tenant_id AND latest.marketing_task_id = d.marketing_task_id AND latest.group_key = d.group_key LEFT JOIN latest_protocol protocol ON protocol.tenant_id = d.tenant_id AND protocol.marketing_task_id = d.marketing_task_id AND protocol.group_key = d.group_key LEFT JOIN latest_ended ended ON ended.tenant_id = d.tenant_id AND ended.marketing_task_id = d.marketing_task_id AND ended.group_key = d.group_key LEFT JOIN failure_reasons failures ON failures.tenant_id = d.tenant_id AND failures.marketing_task_id = d.marketing_task_id AND failures.group_key = d.group_key LEFT JOIN group_link_preview preview ON preview.tenant_id = d.tenant_id AND preview.group_link_id = COALESCE(latest.group_link_id, fixed.group_link_id) LEFT JOIN group_link_health health ON health.tenant_id = d.tenant_id AND health.group_link_id = COALESCE(latest.group_link_id, fixed.group_link_id) LEFT JOIN group_link ON group_link.tenant_id = d.tenant_id AND group_link.id = COALESCE(latest.group_link_id, fixed.group_link_id) LEFT JOIN member_counts members ON members.tenant_id = d.tenant_id AND members.group_jid = COALESCE(latest.group_jid, fixed.group_jid) LEFT JOIN latest_group_setting group_setting ON group_setting.tenant_id = d.tenant_id AND group_setting.group_jid = COALESCE(latest.group_jid, fixed.group_jid) LEFT JOIN sender_group_setting sender_setting ON sender_setting.tenant_id = d.tenant_id AND sender_setting.group_jid = COALESCE(latest.group_jid, fixed.group_jid) AND sender_setting.observer_account_id = COALESCE(latest.account_id, fixed.sender_account_id) LEFT JOIN current_member_roles sender_member ON sender_member.tenant_id = d.tenant_id AND sender_member.group_jid = COALESCE(latest.group_jid, fixed.group_jid) AND sender_member.phone = REGEXP_REPLACE( COALESCE(latest.account_phone, fixed.sender_phone), '[^0-9]', '') LEFT JOIN account_group_membership sender_relation ON sender_relation.tenant_id = d.tenant_id AND sender_relation.account_id = COALESCE(latest.account_id, fixed.sender_account_id) AND sender_relation.group_jid = COALESCE(latest.group_jid, fixed.group_jid) AND sender_relation.deleted_at IS NULL LEFT JOIN account_state account_state ON account_state.tenant_id = d.tenant_id AND account_state.account_id = COALESCE(latest.account_id, fixed.sender_account_id) )
